    if tutar is None:
        return None

    # Sayı ise direkt dön (float olarak)
    if isinstance(tutar, (int, float)):
        try:
            return float(tutar)
        except:
            return None

    # String ise işle
    s = str(tutar).strip()

    # ₺ ve TL karakterlerini kaldır
    s = re.sub(r'[₺TL]', '', s)
    s = s.strip()

    if not s:
        return None

    nokta_sayisi = s.count('.')
    virgul_sayisi = s.count(',')

    # Hem nokta hem virgül varsa
    if nokta_sayisi > 0 and virgul_sayisi > 0:
        # Noktadan sonra tam 3 rakam varsa, nokta binlik ayırıcıdır
        son_noktanin_sonrasindaki_rakamlar = s.split('.')[1] if '.' in s else ''
        if len(son_noktanin_sonrasindaki_rakamlar) == 3 and son_noktanin_sonrasindaki_rakamlar.isdigit():
