            s = s.replace('.', '')
            s = s.replace(',', '.')
    elif nokta_sayisi > 0 and virgul_sayisi == 0:
        # Sadece nokta var - noktadan sonra tam 3 rakam mı?
        son_noktanin_sonrasindaki_rakamlar = s.split('.')[1] if '.' in s else ''
        if len(son_noktanin_sonrasindaki_rakamlar) == 3 and son_noktanin_sonrasindaki_rakamlar.isdigit():
            # Nokta binlik ayırıcı - kaldır
            s = s.replace('.', '')
        else:
            # Nokta ondalık ayırıcı
            return float(s)
    elif nokta_sayisi == 0 and virgul_sayisi > 0:
        # Sadece virgül var - ondalık ayırıcı
        s = s.replace(',', '.')

    try:
        result = float(s)
        return round(result, 2)
    except:
        return None


